function makeRibbon(offset,band,mat,N=850){const verts=[],uvs=[],indices=[];for(let i=0;i<=N;i++){const t=i/N,p=curve.getPointAt(t),tan=curve.getTangentAt(t),normal=new THREE.Vector3(-tan.z,0,tan.x).normalize();for(const side of [-1,1]){const q=p.clone().addScaledVector(normal,offset+side*band/2);verts.push(q.x,q.y+.03,q.z);uvs.push(side===1?1:0,i/10);}if(i<N){const a=i*2;indices.push(a,a+2,a+1,a+1,a+2,a+3);}}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));geo.setAttribute('uv',new THREE.Float32BufferAttribute(uvs,2));geo.setIndex(indices);geo.computeVertexNormals();const m=mesh(geo,mat);mat.side=THREE.DoubleSide;return m;}
